import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type SaasSystemAnimationProps = Record<string, any>;

// ------------------------------------------------------------------
// SVG ICONS (Clean Line Style)
// ------------------------------------------------------------------
