const ShieldIcon = ({ color, strokeWidth }: { color: string; strokeWidth: number }) => (
  <svg viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" style={{ width: '100%', height: '100%' }}>
    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
  </svg>
);

const GraphIcon = ({ color, strokeWidth }: { color: string; strokeWidth: number }) => (
  <svg viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" style={{ width: '100%', height: '100%' }}>
    <polyline points="3 3 3 21 21 21" />
    <polyline points="3 14 8 9 13 14 21 5" />
  </svg>
);

// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------
const SaasSystemAnimation: React.FC<SaasSystemAnimationProps> = ({
  backgroundColor = "#3A006A",
  iconColor = "#FFFFFF",
  heartColor = "#FF4D8D",
  strokeWidth = 2,
  transparentBackground = false,
  durationInSeconds = 10,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Timeline
  const masterOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const organizeProgress = interpolate(frame, [132, 155], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });

  // Base Data Structure
  const humans = [
    { id: 0, scatX: width * 0.20, scatY: height * 0.25, alignX: width * 0.30, alignY: height * 0.25, pulseRate: 0.20, appStart: 15 },
    { id: 1, scatX: width * 0.35, scatY: height * 0.55, alignX: width * 0.30, alignY: height * 0.50, pulseRate: 0.12, appStart: 25 },
    { id: 2, scatX: width * 0.15, scatY: height * 0.80, alignX: width * 0.30, alignY: height * 0.75, pulseRate: 0.35, appStart: 35 },
  ];

  const supports = [
    { id: 0, type: "calendar", scatX: width * 0.80, scatY: height * 0.20, alignX: width * 0.70, alignY: height * 0.20, appStart: 48 },
    { id: 1, type: "chat",     scatX: width * 0.65, scatY: height * 0.45, alignX: width * 0.70, alignY: height * 0.40, appStart: 55 },
    { id: 2, type: "shield",   scatX: width * 0.85, scatY: height * 0.70, alignX: width * 0.70, alignY: height * 0.60, appStart: 62 },
    { id: 3, type: "graph",    scatX: width * 0.70, scatY: height * 0.85, alignX: width * 0.70, alignY: height * 0.80, appStart: 68 },
  ];

  const connections = [
    { hId: 0, sId: 1, delay: 0 },
    { hId: 1, sId: 0, delay: 5 },
    { hId: 1, sId: 3, delay: 10 },
    { hId: 2, sId: 2, delay: 7 },
  ];

  // Calculate current positions based on the "organize" phase
  const getX = (item: { scatX: number; alignX: number }) => interpolate(organizeProgress, [0, 1], [item.scatX, item.alignX]);
  const getY = (item: { scatY: number; alignY: number }) => interpolate(organizeProgress, [0, 1], [item.scatY, item.alignY]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, opacity: masterOpacity }}>
      
      {/* BACKGROUND SVG FOR LINES */}
      <svg style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible", transition: "none" }}>
        {connections.map((conn, i) => {
          const human = humans[conn.hId];
          const support = supports[conn.sId];

          const startX = getX(human);
          const startY = getY(human);
          const targetX = getX(support);
          const targetY = getY(support);

          // Line extends from 78 to ~108 (staggered by delay)
          const lineStartFrame = 78 + conn.delay;
          const lineProg = interpolate(frame, [lineStartFrame, lineStartFrame + 25], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.inOut(Easing.quad),
          });

          if (lineProg === 0) return null;

          // Wandering logic during search phase
          const wanderAmt = Math.sin((frame - 78) * 0.15 + i * 2) * 150;
          const wanderGating = Math.sin(lineProg * Math.PI); // 0 at start, 1 in middle, 0 at target
          
          const currX = interpolate(lineProg, [0, 1], [startX, targetX]);
          const currY = interpolate(lineProg, [0, 1], [startY, targetY]) + (wanderAmt * wanderGating);

          // Smooth S-curve control points
          const cp1x = startX + (currX - startX) * 0.5;
          const cp1y = startY;
          const cp2x = currX - (currX - startX) * 0.5;
          const cp2y = currY;

          return (
            <g key={`conn-${i}`}>
              <path
                d={`M ${startX} ${startY} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${currX} ${currY}`}
                fill="none"
                stroke={iconColor}
                strokeWidth={strokeWidth * 0.6}
                opacity={0.4}
                style={{ transition: "none" }}
              />
              {/* Searching Head Dot */}
              {lineProg < 1 && (
                <circle cx={currX} cy={currY} r={strokeWidth * 1.5} fill={iconColor} opacity={0.8} />
              )}
            </g>
          );
        })}
      </svg>

      {/* FOREGROUND NODES */}
      <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", pointerEvents: "none" }}>
        
        {/* Human Nodes */}
        {humans.map((h) => {
          const x = getX(h);
          const y = getY(h);
          const op = interpolate(frame, [h.appStart, h.appStart + 15], [0, 1], { extrapolateRight: "clamp" });
          const heartScale = 1 + Math.sin(frame * h.pulseRate) * 0.25;

          return (
            <div
              key={`h-${h.id}`}
              style={{
                position: "absolute",
                left: x - 32,
                top: y - 32,
                width: 64,
                height: 64,
                opacity: op,
                transform: `scale(${op})`,
                transition: "none",
              }}
            >
              <HumanIcon color={iconColor} strokeWidth={strokeWidth} />
              <div
                style={{
                  position: "absolute",
                  top: -8,
                  right: -8,
                  width: 24,
                  height: 24,
                  transform: `scale(${heartScale})`,
                  transition: "none",
                }}
              >
                <HeartIcon color={heartColor} />
              </div>
            </div>
          );
        })}

        {/* Support Nodes */}
        {supports.map((s) => {
          const x = getX(s);
          const y = getY(s);
          const op = interpolate(frame, [s.appStart, s.appStart + 15], [0, 1], { extrapolateRight: "clamp" });

          return (
            <div
              key={`s-${s.id}`}
              style={{
                position: "absolute",
                left: x - 32,
                top: y - 32,
                width: 64,
                height: 64,
                opacity: op,
                transform: `scale(${op})`,
                transition: "none",
              }}
            >
              {s.type === "calendar" && <CalendarIcon color={iconColor} strokeWidth={strokeWidth} />}
              {s.type === "chat" && <ChatIcon color={iconColor} strokeWidth={strokeWidth} />}
              {s.type === "shield" && <ShieldIcon color={iconColor} strokeWidth={strokeWidth} />}
              {s.type === "graph" && <GraphIcon color={iconColor} strokeWidth={strokeWidth} />}
            </div>
          );
        })}

      </div>
    </AbsoluteFill>
  );
};

export default SaasSystemAnimation;